import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"AI Core SIMD编程","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/ai_core_simd_programming"},{"text":"基于Tensor的C++编程","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/cpp_tensor_programming_overview"},{"text":"Reg矢量计算编程","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/reg_vector_computation"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/reg_vector_computation.md","filePath":"guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/reg_vector_computation.md","outlineHeaders":[{"level":2,"title":"基础API定位","slug":"基础API定位","link":"#基础API定位"},{"level":2,"title":"与C API的对应关系","slug":"与C-API的对应关系","link":"#与C-API的对应关系"},{"level":2,"title":"模板参数体系","slug":"模板参数体系","link":"#模板参数体系"},{"level":3,"title":"数据类型模板参数","slug":"数据类型模板参数","link":"#数据类型模板参数"},{"level":3,"title":"搬运模式模板参数","slug":"搬运模式模板参数","link":"#搬运模式模板参数"},{"level":3,"title":"MaskMergeMode模板参数","slug":"MaskMergeMode模板参数","link":"#MaskMergeMode模板参数"},{"level":2,"title":"数据对象与寄存器类型","slug":"数据对象与寄存器类型","link":"#数据对象与寄存器类型"},{"level":3,"title":"与LocalTensor衔接","slug":"与LocalTensor衔接","link":"#与LocalTensor衔接"},{"level":2,"title":"特性描述","slug":"特性描述","link":"#特性描述"},{"level":3,"title":"寄存器构造类","slug":"寄存器构造类","link":"#寄存器构造类"},{"level":4,"title":"Mask创建","slug":"Mask创建","link":"#Mask创建"},{"level":4,"title":"地址寄存器创建","slug":"地址寄存器创建","link":"#地址寄存器创建"},{"level":3,"title":"数据搬运类","slug":"数据搬运类","link":"#数据搬运类"},{"level":4,"title":"通用搬运","slug":"通用搬运","link":"#通用搬运"},{"level":4,"title":"对齐搬运","slug":"对齐搬运","link":"#对齐搬运"},{"level":4,"title":"非对齐搬运","slug":"非对齐搬运","link":"#非对齐搬运"},{"level":3,"title":"矢量计算类","slug":"矢量计算类","link":"#矢量计算类"},{"level":4,"title":"RegTensor<T>与RegTensor<T>计算","slug":"RegTensor<T>与RegTensor<T>计算","link":"#RegTensor<T>与RegTensor<T>计算"},{"level":4,"title":"MaskReg计算","slug":"MaskReg计算","link":"#MaskReg计算"},{"level":3,"title":"同步控制类","slug":"同步控制类","link":"#同步控制类"},{"level":2,"title":"编程示例","slug":"编程示例","link":"#编程示例"},{"level":2,"title":"小结","slug":"小结","link":"#小结"}],"lastUpdated":1787050286000}'),l={name:"guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/reg_vector_computation.md"};function e(o,s,t,d,r,g){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>Reg矢量计算编程<span id="ZH-CN_TOPIC_0000002509863892"></span></h1><p>本文介绍如何使用基础API（C++模板接口）编写Reg矢量计算代码。基础API与<a href="../c_pointer_programming/reg_vector_computation.html">Reg矢量计算编程（语言扩展C API）</a>描述的是同一套Reg矢量硬件能力，功能语义一致，主要区别在于API命名、类型表达和可配置参数的表达方式。</p><p>Reg矢量编程的硬件原理、内存层级、VF函数执行域、流水线同步、Hardware Loop、VF融合等与API接口命名无关的内容，请参见<a href="../c_pointer_programming/reg_vector_computation.html">Reg矢量计算编程（语言扩展C API）</a>。本文只说明基础API的接口定位、模板参数、数据类型体系、API分类和典型调用方式。</p><h2 id="基础API定位">基础API定位<span id="section_part1"></span><a class="header-anchor" href="#基础API定位">​</a></h2><p>基础API Reg矢量计算接口位于<code>AscendC::Reg</code>命名空间，是语言扩展C API的C++模板化封装。基础API并不改变Reg矢量计算的编程模型：仍然需要在<code>__aicore__</code>域通过<code>asc_vf_call</code>进入<code>__simd_vf__</code>函数，并在VF函数内完成<code>Load</code> -&gt; <code>Compute</code> -&gt; <code>Store</code>。</p><p>基础API的主要特点如下：</p><ul><li>使用C++类型表达寄存器对象，例如<code>RegTensor&lt;T&gt;</code>、<code>MaskReg</code>、<code>AddrReg</code>、<code>UnalignRegForLoad</code>、<code>UnalignRegForStore</code> ,对应关系参考<a href="#section_part4">数据对象与寄存器类型</a>。</li><li>使用模板参数表达数据类型、搬运模式、PostUpdate模式等配置。</li><li>多数接口可通过参数自动推导寄存器类型。</li><li>搬运接口可以与<code>LocalTensor</code>衔接，可以支持不操作Unified Buffer（UB）地址，也可以外层<code>__aicore__</code>代码从<code>LocalTensor::GetPhyAddr()</code>获取UB物理地址，再传入VF函数内的Reg搬运接口。</li><li>部分计算接口提供<code>MaskMergeMode</code>模板参数，用于控制未被mask选中的元素如何写入目的寄存器。</li></ul><blockquote><p>📌 <strong>提示</strong>：</p><ol><li><p>基础API和C API功能一致。若需要理解“为什么需要Reg矢量编程”“寄存器与UB/GM的关系”“哪些场景需要同步”等模型性内容，请直接阅读C API版本文档。</p></li><li><p>搬运接口支持<code>LocalTensor</code>参数，在后续版本提供，暂未支持。</p></li></ol></blockquote><h2 id="与C-API的对应关系">与C API的对应关系<span id="section_part2"></span><a class="header-anchor" href="#与C-API的对应关系">​</a></h2><p>基础API与C API的核心差异是表达形式不同。</p><table><thead><tr><th>维度</th><th>基础API（C++模板）</th><th>C API（语言扩展）</th></tr></thead><tbody><tr><td>命名空间/前缀</td><td><code>AscendC::Reg::*</code></td><td><code>asc_*</code></td></tr><tr><td>命名风格</td><td><code>LoadAlign</code>、<code>StoreUnAlignPost</code></td><td><code>asc_loadalign</code>、<code>asc_storeunalign_post</code></td></tr><tr><td>矢量数据寄存器</td><td><code>RegTensor&lt;T&gt;</code></td><td><code>vector_float</code>、<code>vector_half</code>、<code>vector_int32_t</code>等</td></tr><tr><td>掩码寄存器</td><td><code>MaskReg</code></td><td><code>vector_bool</code></td></tr><tr><td>地址寄存器</td><td><code>AddrReg</code></td><td><code>addr_reg</code></td></tr><tr><td>非对齐搬入/搬出寄存器</td><td><code>UnalignRegForLoad</code> / <code>UnalignRegForStore</code></td><td><code>vector_load_unalign</code> / <code>vector_store_unalign</code></td></tr><tr><td>数据类型选择</td><td>模板参数<code>T</code>，通常可由参数推导</td><td>类型名或接口后缀，例如<code>_b8</code>、<code>_b16</code>、<code>_b32</code></td></tr><tr><td>PostUpdate</td><td><code>PostLiteral</code>模板参数</td><td>接口名后缀，例如<code>_postupdate</code></td></tr><tr><td>Mask合并模式</td><td><code>MaskMergeMode</code>模板参数</td><td>暂不支持</td></tr></tbody></table><p>常见API映射如下：</p><table><thead><tr><th>功能</th><th>基础API</th><th>C API</th></tr></thead><tbody><tr><td>创建全量mask</td><td><code>CreateMask&lt;T, MaskPattern::ALL&gt;()</code></td><td><code>asc_create_mask_b*()</code></td></tr><tr><td>更新尾块mask</td><td><code>UpdateMask&lt;T&gt;(count)</code></td><td><code>asc_update_mask_b*()</code></td></tr><tr><td>创建地址寄存器</td><td><code>CreateAddrReg&lt;T&gt;(...)</code></td><td><code>asc_update_addr_reg_b*()</code></td></tr><tr><td>通用搬入/搬出</td><td><code>Load</code> / <code>Store</code></td><td><code>asc_load</code> / <code>asc_store</code></td></tr><tr><td>对齐搬入/搬出</td><td><code>LoadAlign</code> / <code>StoreAlign</code></td><td><code>asc_loadalign</code> / <code>asc_storealign</code></td></tr><tr><td>非对齐搬入</td><td><code>LoadUnAlignPre</code> + <code>LoadUnAlign</code></td><td><code>asc_loadunalign_pre</code> + <code>asc_loadunalign</code></td></tr><tr><td>非对齐搬出</td><td><code>StoreUnAlign</code> + <code>StoreUnAlignPost</code></td><td><code>asc_storeunalign</code> + <code>asc_storeunalign_post</code></td></tr><tr><td>流水线同步</td><td><code>LocalMemBar&lt;src, dst&gt;()</code></td><td><code>asc_mem_bar(...)</code></td></tr></tbody></table><h2 id="模板参数体系">模板参数体系<span id="section_part3"></span><a class="header-anchor" href="#模板参数体系">​</a></h2><p>基础API把C API中“后缀、枚举、特殊接口名”表达的能力统一收敛到模板参数中。常见模板参数如下。</p><table><thead><tr><th>模板参数</th><th>作用</th><th>典型取值/类型</th><th>常见接口</th></tr></thead><tbody><tr><td><code>T</code></td><td>数据类型</td><td><code>float</code>、<code>half</code>、<code>int32_t</code>等</td><td><code>RegTensor&lt;T&gt;</code>、<code>LoadAlign&lt;T&gt;</code>、<code>Add&lt;T&gt;</code></td></tr><tr><td><code>PostLiteral</code></td><td>搬运后是否更新UB地址</td><td><code>POST_MODE_NORMAL</code>、<code>POST_MODE_UPDATE</code></td><td><code>LoadAlign</code>、<code>StoreAlign</code>、<code>LoadUnAlign</code>、<code>StoreUnAlign</code></td></tr><tr><td><code>LoadDist</code></td><td>搬入模式</td><td><code>DIST_NORM</code>、broadcast类取值等</td><td><code>LoadAlign</code></td></tr><tr><td><code>StoreDist</code></td><td>搬出模式</td><td>正常搬出、首元素搬出、pack类取值等</td><td><code>StoreAlign</code></td></tr><tr><td><code>MaskMergeMode</code></td><td>mask未选中元素处理方式</td><td><code>ZEROING</code>、<code>MERGING</code></td><td>部分计算接口，例如Add</td></tr><tr><td>计算模式枚举</td><td>指定算法或计算变体</td><td>例如<code>ReduceType</code>、<code>PairReduce</code>等</td><td>规约、复合计算等</td></tr></tbody></table><h3 id="数据类型模板参数">数据类型模板参数<a class="header-anchor" href="#数据类型模板参数">​</a></h3><p>基础API使用<code>RegTensor&lt;T&gt;</code>表达矢量数据寄存器。<code>T</code>决定寄存器内元素解释方式，寄存器宽度仍由硬件VL决定。例如在VL为256B时，<code>RegTensor&lt;float&gt;</code>可表示64个<code>float</code>元素，<code>RegTensor&lt;half&gt;</code>可表示128个<code>half</code>元素。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">srcReg</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstReg</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
</code></pre></div><p>当接口参数已经包含<code>RegTensor&lt;T&gt;</code>时，模板参数<code>T</code>通常可由编译器推导；当使用特定模式、转换接口或需要消除歧义时，可以显式填写。</p><h3 id="搬运模式模板参数">搬运模式模板参数<a class="header-anchor" href="#搬运模式模板参数">​</a></h3><p>基础API使用<code>LoadDist</code>、<code>StoreDist</code>、<code>PostLiteral</code>等模板参数表达搬运模式。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 对齐搬入，使用LoadDist模板参数</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadDist</span><span class="o">::</span><span class="n">DIST_BRC_B32</span><span class="o">&gt;</span><span class="p">(</span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">);</span>

<span class="c1">// PostUpdate对齐搬入，接口执行后更新srcAddr。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">PostLiteral</span><span class="o">::</span><span class="n">POST_MODE_UPDATE</span><span class="o">&gt;</span><span class="p">(</span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">,</span><span class="w"> </span><span class="n">stride</span><span class="p">);</span>

<span class="c1">// 对齐搬出，使用StoreDist模板参数</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreDist</span><span class="o">::</span><span class="n">DIST_FIRST_ELEMENT_B32</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
</code></pre></div><h3 id="MaskMergeMode模板参数">MaskMergeMode模板参数<a class="header-anchor" href="#MaskMergeMode模板参数">​</a></h3><p>部分Reg计算接口提供<code>MaskMergeMode</code>模板参数，用于描述mask未选中元素在目的寄存器中的处理方式：</p><ul><li><code>MaskMergeMode::ZEROING</code>：mask未选中的元素在<code>dstReg</code>中置零。</li><li><code>MaskMergeMode::MERGING</code>：mask未选中的元素保留<code>dstReg</code>原值。</li></ul><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Add</span><span class="o">&lt;</span><span class="n">T</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskMergeMode</span><span class="o">::</span><span class="n">ZEROING</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">src0Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Add</span><span class="o">&lt;</span><span class="n">T</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskMergeMode</span><span class="o">::</span><span class="n">MERGING</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">src0Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
</code></pre></div><blockquote><p>📌 <strong>提示</strong>：<code>MaskMergeMode</code>只有部分接口形态支持，由软件仿真实现。实际使用时应以单个API文档中的函数原型和参数说明为准。对于不需要保留未选中元素旧值的场景，使用默认的<code>ZEROING</code>语义。</p></blockquote><h2 id="数据对象与寄存器类型">数据对象与寄存器类型<span id="section_part4"></span><a class="header-anchor" href="#数据对象与寄存器类型">​</a></h2><p>基础API使用C++类型表达Reg矢量编程中的寄存器资源。</p><table><thead><tr><th>寄存器分类</th><th>基础API类型</th><th>用途</th></tr></thead><tbody><tr><td>矢量数据寄存器</td><td><code>RegTensor&lt;T, regTrait&gt;</code></td><td>保存VL或多VL长度的矢量数据，是计算接口的主要源/目的操作数</td></tr><tr><td>掩码寄存器</td><td><code>MaskReg</code></td><td>控制哪些元素参与计算，也可承载比较、逻辑等结果</td></tr><tr><td>地址寄存器</td><td><code>AddrReg</code></td><td>保存UB访问偏移，适合固定stride、多维索引等搬运场景</td></tr><tr><td>搬入非对齐寄存器</td><td><code>UnalignRegForLoad</code></td><td>连续非对齐搬入的临时缓存</td></tr><tr><td>搬出非对齐寄存器</td><td><code>UnalignRegForStore</code></td><td>连续非对齐搬出的临时缓存</td></tr></tbody></table><p><code>RegTensor</code>和<code>MaskReg</code>等寄存器对象只能作为整体使用，不能按C++数组方式访问其中某个元素。相关硬件含义、宽度、mask bit对应关系请参考<a href="../c_pointer_programming/reg_vector_computation.html">Reg矢量计算编程（语言扩展C API）</a>中“寄存器类型与申请”章节。</p><h3 id="与LocalTensor衔接">与LocalTensor衔接<a class="header-anchor" href="#与LocalTensor衔接">​</a></h3><p>Reg矢量搬运接口实际访问的是UB地址。基于Tensor的Cpp编程中，外层通常使用<code>LocalTensor</code>管理UB数据。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Compute</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">T</span><span class="p">,</span><span class="w"> </span><span class="n">TILE_LENGTH</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// 参数计算等</span>
<span class="w">    </span><span class="p">......</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">AddVF</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// 尾处理</span>
<span class="w">    </span><span class="p">......</span>
<span class="p">}</span>
</code></pre></div><p>这种写法使基础API能够与<code>__aicore__</code>中<code>LocalTensor</code>流程衔接。</p><blockquote><p>📌 <strong>提示</strong>：使用LocalTensor作为VF函数参数时，不能使用引用LocalTensor &amp;。因为在<code>__aicore__</code>和<code>__simd_vf__</code>是两个相互隔离的执行域，无法通过跨执行域通过引用访问。</p></blockquote><h2 id="特性描述">特性描述<span id="section_part5"></span><a class="header-anchor" href="#特性描述">​</a></h2><h3 id="寄存器构造类">寄存器构造类<a class="header-anchor" href="#寄存器构造类">​</a></h3><h4 id="Mask创建">Mask创建<a class="header-anchor" href="#Mask创建">​</a></h4><p><a href="../../../../../api/SIMD-API/basic_api/reg_vector_compute/register_data_types/MaskReg.html"><code>CreateMask</code></a>用于创建固定模式的<code>MaskReg</code>，<a href="../../../../../api/SIMD-API/basic_api/reg_vector_compute/register_data_types/MaskReg.html"><code>UpdateMask</code></a>用于根据剩余元素数生成尾块mask。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">fullMask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">CreateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskPattern</span><span class="o">::</span><span class="n">ALL</span><span class="o">&gt;</span><span class="p">();</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">UpdateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">(</span><span class="n">remainCount</span><span class="p">);</span>
</code></pre></div><p><code>UpdateMask&lt;T&gt;(remainCount)</code>适合放在VF循环中进行尾块处理。其语义与C API中的<code>asc_update_mask_b*</code>一致。</p><h4 id="地址寄存器创建">地址寄存器创建<a class="header-anchor" href="#地址寄存器创建">​</a></h4><p><a href="../../../../../api/SIMD-API/basic_api/reg_vector_compute/register_data_types/AddrReg.html"><code>CreateAddrReg</code></a>用于创建保存UB偏移量的<code>AddrReg</code>，最多支持四层循环跳转。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">AddrReg</span><span class="w"> </span><span class="n">aReg</span><span class="p">;</span>
<span class="k">for</span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">extent1</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="o">++</span><span class="p">){</span>
<span class="w">    </span><span class="k">for</span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">j</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="n">j</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">extent2</span><span class="p">;</span><span class="w"> </span><span class="n">j</span><span class="o">++</span><span class="p">){</span>
<span class="w">        </span><span class="k">for</span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="n">k</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">extent3</span><span class="p">;</span><span class="w"> </span><span class="n">k</span><span class="o">++</span><span class="p">){</span>
<span class="w">            </span><span class="k">for</span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">m</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="n">m</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">extent4</span><span class="p">;</span><span class="w"> </span><span class="n">m</span><span class="o">++</span><span class="p">){</span>
<span class="w">                </span><span class="n">aReg</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">CreateAddrReg</span><span class="p">(</span><span class="n">i</span><span class="p">,</span><span class="w"> </span><span class="n">const1</span><span class="p">,</span><span class="w"> </span><span class="n">j</span><span class="p">,</span><span class="w"> </span><span class="n">const2</span><span class="p">,</span><span class="w"> </span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">const3</span><span class="p">,</span><span class="w"> </span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">const4</span><span class="p">);</span>
<span class="w">                </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">,</span><span class="w"> </span><span class="n">aReg</span><span class="p">);</span>
<span class="w">            </span><span class="p">}</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><h3 id="数据搬运类">数据搬运类<a class="header-anchor" href="#数据搬运类">​</a></h3><h4 id="通用搬运">通用搬运<a class="header-anchor" href="#通用搬运">​</a></h4><p><code>Load</code> / <code>Store</code>不要求用户区分UB地址是否32B对齐，适合希望统一处理对齐和非对齐地址的场景。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Load</span><span class="p">(</span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Store</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Store</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">count</span><span class="p">);</span>
</code></pre></div><p>通用搬运是软件封装，性能敏感且地址满足对齐条件时，优先使用对齐搬运。</p><h4 id="对齐搬运">对齐搬运<a class="header-anchor" href="#对齐搬运">​</a></h4><p><a href="../../../../../api/SIMD-API/basic_api/reg_vector_compute/reg_data_load/LoadAlign_continuous.html"><code>LoadAlign</code></a> / <a href="../../../../../api/SIMD-API/basic_api/reg_vector_compute/reg_data_store/StoreAlign_continuous.html"><code>StoreAlign</code></a>适用于UB地址满足对齐要求的连续搬入/搬出，是Reg矢量编程中最常见的搬运接口。在搬运时可以按照内置的功能随路进行数据排布等操作，具体功能以对应API章节为准。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
</code></pre></div><h4 id="非对齐搬运">非对齐搬运<a class="header-anchor" href="#非对齐搬运">​</a></h4><p>连续非对齐搬入由<a href="../../../../../api/SIMD-API/basic_api/reg_vector_compute/reg_data_load/LoadUnAlign_continuous.html"><code>LoadUnAlignPre</code></a>和<a href="../../../../../api/SIMD-API/basic_api/reg_vector_compute/reg_data_load/LoadUnAlign_continuous.html"><code>LoadUnAlign</code></a>组合使用；连续非对齐搬出由<a href="../../../../../api/SIMD-API/basic_api/reg_vector_compute/reg_data_store/StoreUnAlign_continuous.html"><code>StoreUnAlign</code></a>和<a href="../../../../../api/SIMD-API/basic_api/reg_vector_compute/reg_data_store/StoreUnAlign_continuous.html"><code>StoreUnAlignPost</code></a>组合使用。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">UnalignRegForLoad</span><span class="w"> </span><span class="n">loadUreg</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">UnalignRegForStore</span><span class="w"> </span><span class="n">storeUreg</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadUnAlignPre</span><span class="p">(</span><span class="n">loadUreg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">);</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadUnAlign</span><span class="p">(</span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">loadUreg</span><span class="p">,</span><span class="w"> </span><span class="n">srcAddr</span><span class="p">,</span><span class="w"> </span><span class="n">postUpdateStride</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// Reg计算</span>
<span class="w">    </span><span class="p">...</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreUnAlign</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">storeUreg</span><span class="p">,</span><span class="w"> </span><span class="n">postUpdateStride</span><span class="p">);</span>
<span class="p">}</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreUnAlignPost</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">storeUreg</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
</code></pre></div><h3 id="矢量计算类">矢量计算类<a class="header-anchor" href="#矢量计算类">​</a></h3><p>矢量计算接口直接操作<code>RegTensor&lt;T&gt;</code>或<code>MaskReg</code>，通常带有<code>MaskReg mask</code>控制有效元素。</p><h4 id="RegTensor&lt;T&gt;与RegTensor&lt;T&gt;计算"><code>RegTensor&lt;T&gt;</code>与<code>RegTensor&lt;T&gt;</code>计算<a class="header-anchor" href="#RegTensor&lt;T&gt;与RegTensor&lt;T&gt;计算">​</a></h4><p>基础算术接口完成寄存器之间的逐元素计算，标量算术接口完成寄存器与标量的逐元素计算。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">src0Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Mul</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">src0Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Adds</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">scalarValue</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Muls</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">scalarValue</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
</code></pre></div><h4 id="MaskReg计算"><code>MaskReg</code>计算<a class="header-anchor" href="#MaskReg计算">​</a></h4><p>逻辑接口可操作<code>RegTensor</code>或<code>MaskReg</code>；比较接口通常输出比较结果，选择接口按mask在两个源操作数之间选择。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">And</span><span class="p">(</span><span class="n">dstMaskReg</span><span class="p">,</span><span class="w"> </span><span class="n">src0MaskReg</span><span class="p">,</span><span class="w"> </span><span class="n">src1MaskReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Compare</span><span class="p">(</span><span class="n">cmpMaskReg</span><span class="p">,</span><span class="w"> </span><span class="n">src0Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Select</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">src0Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">,</span><span class="w"> </span><span class="n">cmpMaskReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
</code></pre></div><p>这些接口往往有更多模板参数或限制条件，建议在具体使用时查看对应API页面。</p><h3 id="同步控制类">同步控制类<a class="header-anchor" href="#同步控制类">​</a></h3><p>基础API使用<a href="../../../../../api/SIMD-API/basic_api/reg_vector_compute/sync_control/LocalMemBar.html"><code>LocalMemBar</code></a>表达VF内部对UB访问流水线的同步约束。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Store</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LocalMemBar</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MemType</span><span class="o">::</span><span class="n">VEC_STORE</span><span class="p">,</span>
<span class="w">                          </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MemType</span><span class="o">::</span><span class="n">VEC_LOAD</span><span class="o">&gt;</span><span class="p">();</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Load</span><span class="p">(</span><span class="n">srcReg</span><span class="p">,</span><span class="w"> </span><span class="n">dstAddr</span><span class="p">);</span>
</code></pre></div><p>何时需要同步与API命名无关，判断规则请参考<a href="../c_pointer_programming/reg_vector_computation.html">Reg矢量计算编程（语言扩展C API）</a>中的“流水线同步”章节。</p><h2 id="编程示例">编程示例<span id="section_part6"></span><a class="header-anchor" href="#编程示例">​</a></h2><p>下面示例展示基础API的典型调用方式。外层<code>__aicore__</code>函数仍负责<code>LocalTensor</code>管理，VF函数内使用Reg基础API完成搬入、计算和搬出。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">AddVFv1</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                              </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span>
<span class="w">                              </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src1</span><span class="p">,</span>
<span class="w">                              </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span>
<span class="w">                              </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src0Reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">CreateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskPattern</span><span class="o">::</span><span class="n">ALL</span><span class="o">&gt;</span><span class="p">();</span>

<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">;</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">src0Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src0</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">src1Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">src0Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="p">(</span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">AddVFv2</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">dstAddr</span><span class="p">,</span>
<span class="w">                                </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src0Addr</span><span class="p">,</span>
<span class="w">                                </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">src1Addr</span><span class="p">,</span>
<span class="w">                                </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span>
<span class="w">                                </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src0Reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">RegTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstReg</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">CreateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskPattern</span><span class="o">::</span><span class="n">ALL</span><span class="o">&gt;</span><span class="p">();</span>

<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">;</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">src0Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src0Addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">LoadAlign</span><span class="p">(</span><span class="n">src1Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1Addr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">src0Reg</span><span class="p">,</span><span class="w"> </span><span class="n">src1Reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">StoreAlign</span><span class="p">(</span><span class="n">dstAddr</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">dstReg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Compute</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="n">T</span><span class="p">,</span><span class="w"> </span><span class="n">TILE_LENGTH</span><span class="o">&gt;</span><span class="p">();</span>

<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">T</span><span class="p">);</span>
<span class="w">    </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">repeatTimes</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">TILE_LENGTH</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">;</span>
<span class="w">	</span><span class="c1">// 使用LocalTensor作为参数</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">AddVFv1</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">);</span>
<span class="w">    </span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">dstAddr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="p">)</span><span class="n">dst</span><span class="p">.</span><span class="n">GetPhyAddr</span><span class="p">();</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">src0Addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="p">)</span><span class="n">src0</span><span class="p">.</span><span class="n">GetPhyAddr</span><span class="p">();</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">src1Addr</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="p">)</span><span class="n">src1</span><span class="p">.</span><span class="n">GetPhyAddr</span><span class="p">();</span>
<span class="w">    </span><span class="c1">// 使用UB地址作为参数</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">AddVFv2</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">dstAddr</span><span class="p">,</span><span class="w"> </span><span class="n">src0Addr</span><span class="p">,</span><span class="w"> </span><span class="n">src1Addr</span><span class="p">,</span><span class="w"> </span><span class="n">oneRepeatSize</span><span class="p">,</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>如果需要处理尾块，可以在VF循环中使用<code>UpdateMask&lt;T&gt;</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">remainCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">count</span><span class="p">;</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">repeatTimes</span><span class="p">;</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">MaskReg</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Reg</span><span class="o">::</span><span class="n">UpdateMask</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="p">(</span><span class="n">remainCount</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// Load / Compute / Store</span>
<span class="p">}</span>
</code></pre></div><h2 id="小结">小结<span id="section_part7"></span><a class="header-anchor" href="#小结">​</a></h2><p>基础API与C API描述的是同一套Reg矢量计算能力，两者的编程模型和硬件语义保持一致。基础API的差异主要体现在接口表达方式上：它通过<code>AscendC::Reg::*</code>命名空间组织接口，使用C++寄存器类型描述VF内部的数据对象，并通过模板参数承载数据类型、搬运模式、计算模式等配置。与<code>LocalTensor</code>衔接时，可以在<code>__aicore__</code>函数中直接将<code>LocalTensor</code>作为参数传入VF函数，也可以通过<code>LocalTensor::GetPhyAddr()</code>取得UB地址后传入VF函数，再在VF函数内部使用Reg搬运接口完成访问。</p></article></div>`,1)])])}const w=a(l,[["render",e]]);export{h as __pageData,w as default};
